<template>
  <section class="report-page">
    <div class="page-intro"><div><p>OPERATIONS DAILY REPORT</p><h2>运营日报填报</h2><span>用一份结构化日报，完成当天经营复盘与本月目标校准。</span></div><a-date-picker v-model:value="selectedDate" value-format="YYYY-MM-DD" :allow-clear="false" @change="loadData" /></div>
    <div class="identity-strip"><div><small>填报人</small><strong>{{ auth.realName }}</strong></div><div><small>所属部门</small><strong>{{ auth.department || '未配置' }}</strong></div><div><small>填报日期</small><strong>{{ selectedDate }}</strong></div><div><small>表单状态</small><strong :class="existing ? 'success' : ''">{{ existing ? '已提交，可更新' : '待提交' }}</strong></div></div>
    <div class="report-grid">
      <a-form ref="formRef" :model="form" layout="vertical" class="form-card" @finish="submit">
        <FormSection title="销售与上架" desc="当月累计口径，直接用于目标完成率计算">
          <div class="field-grid"><a-form-item label="累计销售额" name="cumulative_sales" :rules="requiredNumber"><a-input-number v-model:value="form.cumulative_sales" :min="0" :precision="2" prefix="¥" /></a-form-item><a-form-item label="实际上架数量" name="listing_count" :rules="requiredNumber"><a-input-number v-model:value="form.listing_count" :min="0" :precision="0" /></a-form-item><a-form-item label="产品优化数量" name="optimization_count" :rules="requiredNumber"><a-input-number v-model:value="form.optimization_count" :min="0" :precision="0" /></a-form-item></div>
        </FormSection>
        <FormSection title="合规检查" desc="确认当天是否出现平台风险或商品限制">
          <div class="field-grid"><YesNo v-model="form.violation_triggered" label="是否触发违规 / 扣分" name="violation_triggered"/><YesNo v-model="form.infringement_triggered" label="是否链接侵权 / 禁售" name="infringement_triggered"/><YesNo v-model="form.all_issues_resolved" label="当天问题是否都解决" name="all_issues_resolved"/></div>
        </FormSection>
        <FormSection title="质量与审核" desc="填写审核质量和异常波动监测数据">
          <div class="field-grid"><a-form-item label="备货审核及时率" name="stocking_audit_rate" :rules="requiredNumber"><a-input-number v-model:value="form.stocking_audit_rate" :min="0" :max="100" :precision="2" addon-after="%" /></a-form-item><a-form-item label="产品反推数量" name="reverse_product_count" :rules="requiredNumber"><a-input-number v-model:value="form.reverse_product_count" :min="0" :precision="0" /></a-form-item><a-form-item label="浮动 ≥20% 的店铺数" name="volatile_store_count" :rules="requiredNumber"><a-input-number v-model:value="form.volatile_store_count" :min="0" :precision="0" /></a-form-item></div>
        </FormSection>
        <FormSection title="周度项" :desc="isTuesday ? '今天是周二，请完成周度检查' : '仅周二开放填写，当前已自动锁定'">
          <div class="field-grid"><a-form-item label="周延迟率 / 取消率是否超标"><a-radio-group v-model:value="form.weekly_delay_exceeded" :disabled="!isTuesday"><a-radio :value="true">是</a-radio><a-radio :value="false">否</a-radio></a-radio-group></a-form-item><a-form-item label="周商责差评 ≥3 的链接数"><a-input-number v-model:value="form.weekly_bad_review_links" :disabled="!isTuesday" :min="0" :precision="0" /></a-form-item><a-form-item label="周错发 / 破损 ≥3 的链接数"><a-input-number v-model:value="form.weekly_wrong_damage_links" :disabled="!isTuesday" :min="0" :precision="0" /></a-form-item></div>
        </FormSection>
        <a-button type="primary" html-type="submit" size="large" block :loading="saving">{{ existing ? '更新今日日报' : '提交今日日报' }}</a-button>
      </a-form>
      <aside class="progress-card"><div class="live"><i></i>本月销售进度</div><div class="progress-number">{{ completionRate }}<span>%</span></div><a-progress :percent="Math.min(Number(completionRate),100)" :show-info="false" :stroke-color="progressColor"/><div class="status-chip" :style="{color:progressColor,background:progressColor+'14'}">{{ statusText }}</div><dl><div><dt>本月目标销售额</dt><dd>{{ money(target?.sales_target) }}</dd></div><div><dt>当前累计销售额</dt><dd>{{ money(form.cumulative_sales) }}</dd></div><div><dt>距目标缺口</dt><dd>{{ money(gap) }}</dd></div><div><dt>时间进度</dt><dd>{{ timeProgress }}%</dd></div></dl><p v-if="!target" class="target-empty">本月目标未配置，请联系管理端。</p></aside>
    </div>
  </section>
</template>
<script setup>
import { computed, defineComponent, h, onMounted, reactive, ref } from 'vue'
import dayjs from 'dayjs'
import { message } from 'ant-design-vue'
import { useAuthStore } from '@/stores/auth'
import { getMyDailyReport, submitDailyReport } from '@/services/api'
const auth=useAuthStore(); const selectedDate=ref(dayjs().format('YYYY-MM-DD')); const saving=ref(false); const existing=ref(false); const target=ref(null); const formRef=ref()
const defaults=()=>({cumulative_sales:0,listing_count:0,optimization_count:0,weekly_delay_exceeded:null,violation_triggered:false,infringement_triggered:false,weekly_bad_review_links:null,weekly_wrong_damage_links:null,stocking_audit_rate:0,reverse_product_count:0,volatile_store_count:0,all_issues_resolved:false}); const form=reactive(defaults())
const requiredNumber=[{required:true,message:'请填写该项'}]; const isTuesday=computed(()=>dayjs(selectedDate.value).day()===2); const completionRate=computed(()=>target.value?.sales_target>0?((Number(form.cumulative_sales||0)/Number(target.value.sales_target))*100).toFixed(1):'0.0'); const gap=computed(()=>Math.max(0,Number(target.value?.sales_target||0)-Number(form.cumulative_sales||0))); const timeProgress=computed(()=>Math.round(dayjs(selectedDate.value).date()/dayjs(selectedDate.value).daysInMonth()*100)); const progressColor=computed(()=>Number(completionRate.value)>=100?'#15a46d':Number(completionRate.value)>=timeProgress.value?'#2f7df4':'#e79531'); const statusText=computed(()=>!target.value?'目标未配置':Number(completionRate.value)>=100?'已超额完成':Number(completionRate.value)>=timeProgress.value?'达标中':'进度落后')
const FormSection=defineComponent({props:['title','desc'],setup(p,{slots}){return()=>h('section',{class:'form-section'},[h('header',[h('h3',p.title),h('p',p.desc)]),slots.default?.()])}}); const YesNo=defineComponent({props:['modelValue','label','name'],emits:['update:modelValue'],setup(p,{emit}){return()=>h('div',{class:'yesno'},[h('label',p.label),h('div',{class:'toggle'},[h('button',{type:'button',class:{active:p.modelValue===false},onClick:()=>emit('update:modelValue',false)},'否'),h('button',{type:'button',class:{active:p.modelValue===true,danger:p.modelValue===true},onClick:()=>emit('update:modelValue',true)},'是')])])}})
function money(v){return `¥ ${Number(v||0).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2})}`}
async function loadData(){const data=await getMyDailyReport(selectedDate.value); target.value=data.target; existing.value=!!data.report; Object.assign(form,defaults(),data.report||{}); if(!isTuesday.value) Object.assign(form,{weekly_delay_exceeded:null,weekly_bad_review_links:null,weekly_wrong_damage_links:null})}
async function submit(){saving.value=true;try{await submitDailyReport({...form,report_date:selectedDate.value});message.success(existing.value?'日报已更新':'日报提交成功');await loadData()}finally{saving.value=false}}
onMounted(loadData)
</script>
<style scoped>
.report-page{max-width:1380px;margin:auto}.page-intro{display:flex;align-items:end;justify-content:space-between;margin-bottom:20px}.page-intro p{margin:0 0 5px;color:#2f7df4;font-size:10px;font-weight:700;letter-spacing:.16em}.page-intro h2{margin:0 0 6px;font-size:24px}.page-intro span{color:#7e8ba1;font-size:13px}.identity-strip{display:grid;grid-template-columns:repeat(4,1fr);margin-bottom:18px;border:1px solid #dfe7f2;border-radius:10px;background:#fff}.identity-strip div{padding:15px 18px;border-right:1px solid #edf1f6}.identity-strip div:last-child{border:0}.identity-strip small,.identity-strip strong{display:block}.identity-strip small{margin-bottom:4px;color:#8b98ad}.identity-strip strong{font-size:13px}.success{color:#15a46d}.report-grid{display:grid;grid-template-columns:minmax(0,1fr) 330px;gap:20px;align-items:start}.form-card,.progress-card{border:1px solid #dfe7f2;border-radius:12px;background:#fff;box-shadow:0 8px 26px rgba(39,76,135,.05)}.form-card{padding:24px}.form-section{margin-bottom:25px;padding-bottom:7px;border-bottom:1px solid #edf1f6}.form-section header{margin-bottom:17px}.form-section h3{margin:0 0 4px;font-size:15px}.form-section p{margin:0;color:#8b98ad;font-size:11px}.field-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:0 16px}.field-grid :deep(.ant-input-number){width:100%}.yesno>label{display:block;margin-bottom:8px;font-size:14px}.toggle{display:flex;padding:3px;border:1px solid #d9e2ee;border-radius:7px;background:#f5f8fc}.toggle button{flex:1;padding:7px;border:0;border-radius:5px;color:#7c899e;background:transparent;cursor:pointer}.toggle button.active{color:#1767df;background:#fff;box-shadow:0 1px 5px #dce5f2}.toggle button.danger{color:#d24747}.progress-card{position:sticky;top:105px;padding:23px}.live{display:flex;align-items:center;gap:8px;color:#6f7f98;font-size:12px}.live i{width:8px;height:8px;border-radius:50%;background:#15a46d;box-shadow:0 0 0 5px #e3f7ef}.progress-number{margin:25px 0 8px;font-size:48px;font-weight:750;letter-spacing:-.04em}.progress-number span{font-size:20px}.status-chip{display:inline-block;margin-top:13px;padding:5px 10px;border-radius:20px;font-size:12px;font-weight:600}.progress-card dl{margin:22px 0 0}.progress-card dl div{display:flex;justify-content:space-between;padding:11px 0;border-bottom:1px solid #edf1f6}.progress-card dt{color:#8390a5;font-size:12px}.progress-card dd{margin:0;font-size:12px;font-weight:650}.target-empty{margin:16px 0 0;padding:11px;border-radius:7px;color:#a76613;background:#fff7e8;font-size:11px}@media(max-width:1000px){.report-grid{grid-template-columns:1fr}.progress-card{position:static}.field-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:650px){.page-intro{align-items:start;gap:15px}.identity-strip{grid-template-columns:repeat(2,1fr)}.field-grid{grid-template-columns:1fr}.form-card{padding:17px}}
</style>
